(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-201":{scenario:{legacy:"KK-201"},learning:{summary:{vi:"Chuyên viên chứng từ xuất nhập khẩu lập, kiểm tra và hoàn thiện bộ chứng từ cho từng lô hàng: hóa đơn thương mại, phiếu đóng gói, vận đơn, giấy chứng nhận xuất xứ, bảo hiểm và bộ chứng từ xuất trình theo thư tín dụng (L/C). Mục tiêu là chứng từ khớp nhau, khớp điều kiện L/C và đúng Incoterms để ngân hàng thanh toán và hàng thông quan đúng hạn.",en:"An import-export documentation specialist prepares, checks and completes the document set for each shipment: commercial invoice, packing list, bill of lading, certificate of origin, insurance and the presentation set under a letter of credit (L/C). The goal is documents that match each other, comply with the L/C and the right Incoterms so the bank pays and goods clear on time."},responsibilities:{vi:["Lập hóa đơn thương mại, phiếu đóng gói theo hợp đồng và điều kiện L/C.","Đặt chỗ, theo dõi vận đơn và kiểm tra thông tin tàu, cảng, ngày giao hàng.","Xin giấy chứng nhận xuất xứ (C/O) phù hợp hiệp định thương mại của nước nhập khẩu.","Kiểm tra bộ chứng từ xuất trình, phát hiện bất hợp lệ trước khi nộp ngân hàng.","Lưu hồ sơ lô hàng và phối hợp với kinh doanh, hãng tàu, ngân hàng, hải quan."],en:["Issue the commercial invoice and packing list in line with the contract and L/C terms.","Book space, track the bill of lading and check vessel, port and shipment dates.","Obtain the certificate of origin (C/O) matching the importing country's trade agreement.","Check the presentation set and catch discrepancies before submitting to the bank.","Archive shipment files and coordinate with sales, carriers, banks and customs."]},competencies:[{name:{vi:"Đối chiếu chứng từ",en:"Document matching"},desc:{vi:"So khớp từng trường giữa hóa đơn, phiếu đóng gói, vận đơn, C/O và điều khoản L/C.",en:"Match every field across invoice, packing list, bill of lading, C/O and L/C clauses."}},{name:{vi:"Incoterms & thanh toán quốc tế",en:"Incoterms & trade finance"},desc:{vi:"Hiểu nghĩa vụ, chi phí, rủi ro của các điều kiện giao hàng và phương thức L/C, D/P, T/T.",en:"Understand duties, costs and risks of delivery terms and L/C, D/P and T/T payments."}},{name:{vi:"Chính xác số liệu",en:"Data accuracy"},desc:{vi:"Kiểm soát trọng lượng, số kiện, trị giá và mô tả hàng thống nhất trên mọi chứng từ.",en:"Keep weights, packages, values and descriptions consistent on every document."}},{name:{vi:"Liêm chính nghề nghiệp",en:"Professional integrity"},desc:{vi:"Không lùi ngày, không sửa chứng từ sai sự thật; đề xuất sửa L/C hoặc phương án hợp lệ.",en:"Never backdate or falsify documents; propose an L/C amendment or a compliant alternative."}},{name:{vi:"Quản lý thời hạn",en:"Deadline management"},desc:{vi:"Bám sát ngày cắt máng, hạn giao hàng và hạn xuất trình chứng từ.",en:"Track cut-off times, latest shipment dates and presentation deadlines."}}],knowledge:{vi:["Incoterms 2020 của ICC: EXW, FOB, CFR, CIF, DAP, DDP và phân chia rủi ro, chi phí.","UCP 600 về thư tín dụng và chuẩn mực kiểm tra chứng từ ISBP của ICC.","Các loại vận đơn đường biển, vận đơn hàng không và yêu cầu ký phát.","Quy tắc xuất xứ và các mẫu C/O theo FTA như ATIGA (mẫu D), AJCEP (mẫu AJ), VJEPA (mẫu VJ).","Nghĩa vụ mua bảo hiểm hàng hóa theo CIF/CIP và điều kiện bảo hiểm ICC (A), (B), (C)."],en:["ICC Incoterms 2020: EXW, FOB, CFR, CIF, DAP, DDP and the split of risks and costs.","UCP 600 for letters of credit and the ICC ISBP standard for document examination.","Types of ocean and air waybills and their issuance requirements.","Rules of origin and FTA C/O forms such as ATIGA (Form D), AJCEP (Form AJ) and VJEPA (Form VJ).","Cargo insurance duties under CIF/CIP and Institute Cargo Clauses (A), (B), (C)."]},tools:["ECUS / VNACCS","Cổng eCoSys cấp C/O điện tử","Microsoft Excel","Hệ thống booking của hãng tàu","Phần mềm quản lý lô hàng (TMS)"],kpis:{vi:["Tỷ lệ bộ chứng từ L/C được ngân hàng chấp nhận lần đầu.","Số lô hàng trễ cắt máng do chứng từ (mục tiêu bằng 0).","Thời gian hoàn thiện bộ chứng từ sau ngày tàu chạy.","Số lỗi sai lệch phát hiện trước khi xuất trình."],en:["Share of L/C presentations accepted by the bank first time.","Shipments missing cut-off because of documents (target zero).","Time to complete the document set after vessel departure.","Discrepancies caught before presentation."]},day:[{time:"08:00",vi:"Kiểm tra email khách hàng, hãng tàu và lịch tàu của các lô trong tuần.",en:"Check customer and carrier emails and this week's vessel schedule."},{time:"09:30",vi:"Đối chiếu bản nháp vận đơn với phiếu đóng gói và điều kiện L/C.",en:"Compare the draft bill of lading with the packing list and L/C terms."},{time:"13:00",vi:"Nộp hồ sơ xin C/O và cập nhật hóa đơn theo Incoterms đã thỏa thuận.",en:"Apply for the C/O and update the invoice to the agreed Incoterms."},{time:"15:30",vi:"Xử lý yêu cầu gấp từ kinh doanh, báo cáo rủi ro trước giờ cắt máng.",en:"Handle urgent sales requests and flag risks before the cut-off time."},{time:"17:00",vi:"Hoàn thiện bộ chứng từ, gửi ngân hàng và lưu hồ sơ lô hàng.",en:"Finalize the set, send it to the bank and archive the shipment file."}],mistakes:{vi:["Để Incoterms trên hóa đơn khác điều kiện L/C (ví dụ FOB thay vì CIF).","Ghi trọng lượng trên vận đơn không khớp phiếu đóng gói đã xác nhận.","Chấp nhận lùi ngày vận đơn để được thanh toán, gây rủi ro gian lận chứng từ."],en:["Invoice Incoterms differing from the L/C (for example FOB instead of CIF).","Bill of lading weight not matching the certified packing list.","Agreeing to backdate a bill of lading to get paid, creating document fraud risk."]},career:[{vi:"Nhân viên chứng từ xuất nhập khẩu",en:"Export documentation assistant"},{vi:"Chuyên viên chứng từ & thanh toán quốc tế",en:"Documentation & trade finance specialist"},{vi:"Trưởng nhóm xuất nhập khẩu",en:"Import-export team lead"},{vi:"Quản lý chuỗi cung ứng & xuất nhập khẩu",en:"Supply chain & import-export manager"}],glossary:[{term:"L/C",vi:"Thư tín dụng: cam kết thanh toán của ngân hàng khi người bán xuất trình chứng từ phù hợp.",en:"Letter of credit: a bank's undertaking to pay against complying documents."},{term:"B/L",vi:"Vận đơn đường biển: biên nhận hàng, bằng chứng hợp đồng vận chuyển và chứng từ sở hữu.",en:"Bill of lading: receipt of goods, evidence of carriage contract and document of title."},{term:"Packing List",vi:"Phiếu đóng gói liệt kê số kiện, quy cách, trọng lượng tịnh và cả bì của lô hàng.",en:"List of packages, specifications, net and gross weights of the shipment."},{term:"Discrepancy",vi:"Bất hợp lệ: điểm chứng từ không khớp L/C hoặc không thống nhất giữa các chứng từ.",en:"A point where documents do not comply with the L/C or with each other."},{term:"Cut-off",vi:"Giờ cắt máng: thời hạn cuối giao hàng hoặc chứng từ cho hãng tàu trước khi tàu chạy.",en:"The last time to deliver cargo or documents to the carrier before sailing."}],quiz:[{q:{vi:"Theo CIF, ai có nghĩa vụ mua bảo hiểm hàng hóa?",en:"Under CIF, who must buy cargo insurance?"},options:{vi:["Người mua","Người bán","Hãng tàu","Ngân hàng mở L/C"],en:["The buyer","The seller","The carrier","The issuing bank"]},answer:1,explain:{vi:"CIF yêu cầu người bán mua bảo hiểm cho người mua với mức tối thiểu theo ICC (C).",en:"CIF requires the seller to insure for the buyer, at least on ICC (C) terms."}},{q:{vi:"Trọng lượng trên vận đơn khác phiếu đóng gói đã xác nhận. Bạn làm gì?",en:"The B/L weight differs from the certified packing list. What do you do?"},options:{vi:["Giữ nguyên vì hãng tàu đã cân","Sửa phiếu đóng gói cho khớp vận đơn","Xác minh và sửa vận đơn theo số liệu đã xác nhận trước phát hành","Bỏ qua vì chênh lệch nhỏ"],en:["Keep it because the carrier weighed it","Change the packing list to match","Verify and correct the B/L to the certified figure before issue","Ignore it as a small gap"]},answer:2,explain:{vi:"Chứng từ phải thống nhất; phải xác minh nguồn và sửa trước khi phát hành để tránh bất hợp lệ.",en:"Documents must be consistent; verify the source and correct before issue to avoid discrepancies."}},{q:{vi:"Quy tắc nào điều chỉnh việc kiểm tra chứng từ theo L/C?",en:"Which rules govern document examination under an L/C?"},options:{vi:["UCP 600 và ISBP","Incoterms 2020","Luật Hải quan","ISO 9001"],en:["UCP 600 and ISBP","Incoterms 2020","Customs Law","ISO 9001"]},answer:0,explain:{vi:"UCP 600 quy định nghĩa vụ các bên trong L/C; ISBP hướng dẫn chuẩn kiểm tra chứng từ.",en:"UCP 600 sets L/C obligations; ISBP guides the standard of document examination."}},{q:{vi:"Kinh doanh đề nghị lùi ngày vận đơn để kịp hạn L/C. Phương án đúng là gì?",en:"Sales asks to backdate the B/L to meet the L/C deadline. What is right?"},options:{vi:["Đồng ý nếu trưởng phòng cho phép miệng","Chờ đến khi hết giờ cắt máng","Tự sửa ngày trên bản scan","Từ chối, báo cáo và đề nghị sửa L/C hoặc đổi chuyến hợp lệ"],en:["Agree if the manager says so verbally","Wait until the cut-off passes","Edit the date on the scan yourself","Refuse, escalate and request an L/C amendment or a compliant sailing"]},answer:3,explain:{vi:"Lùi ngày vận đơn là gian lận chứng từ; phải từ chối và tìm phương án hợp lệ.",en:"Backdating a B/L is document fraud; refuse and find a compliant option."}}],tools_en:["ECUS / VNACCS","eCoSys electronic C/O issuance portal","Microsoft Excel","Shipping line booking system","Shipment management software (TMS)"]}}})})(window.KKR);
